mapper.select:
		select id, view_name, page_id, view_json,base_map_json, img_url, create_time, update_time, status from sys_industry_view


				AND id = #{industryViewId}


				AND id in

					#{item}



				AND page_id = #{pageId}


				AND view_name like CONCAT(CONCAT('%', #{viewName}),'%')


				AND status = #{status}


				AND delete_flag = #{deleteFlag}


        order by update_time desc

select view.id viewId , rel.view_name, rel.display_type displayType, view.view_json, view.base_map_json, view.img_url, view.create_time, view.update_time, view.status, rel.industry_view_type, rel.sort from sys_industry_view view inner join sys_industry_view_rel rel on view.id = rel.industry_view_id and rel.industry_view_type = 1 where view.delete_flag = 0 and rel.industry_code = #{industryCode} and rel.app_ver_code = #{appVerCode}
AND view.id in
#{item}

select view.id viewId , rel.view_name, rel.display_type displayType, view.screen_url, view.img_url, view.create_time, view.update_time, rel.industry_view_type, view.screen_compo_type screenCompoType, rel.sort from sys_industry_screen view inner join sys_industry_view_rel rel on view.id = rel.industry_view_id and rel.industry_view_type = 2 where view.delete_flag = 0 and rel.industry_code = #{industryCode} and rel.app_ver_code = #{appVerCode}
AND view.id in
#{item}
